    elif x['ref'] and cnt[x['ref']]>1: notes.append('ref repeated later')
    if x['ref']: seen.setdefault(x['ref'],x['mid'])
    if 'threshold' in x['reason']: notes.append(x['reason'].replace("You're being billed because you reached your ",'threshold ').replace(' payment threshold.',''))
